def solve(grid):
    import sys
    # Copy input to output
    out = [row[:] for row in grid]
    h = len(grid)
    if h == 0:
        return out
    w = len(grid[0])

    # ---------- locate columns that contain any 2 ----------
    wall_cols = []
    col_cnt = {}
    for c in range(w):
        cnt = sum(1 for r in range(h) if grid[r][c] == 2)
        if cnt:
            wall_cols.append(c)
            col_cnt[c] = cnt

    # ---------- determine which rows are "active" (cause a shift) ----------
    # if any wall column has exactly one 2, the column is a wall for every row
    any_single = any(cc == 1 for cc in col_cnt.values())

    if any_single:
        active = [True] * h
    else:
        active = [any(grid[r][c] == 2 for c in range(w)) for r in range(h)]

    # prefix sums of active rows
    pref = [0] * (h + 1)
    for i in range(h):
        pref[i + 1] = pref[i] + (1 if active[i] else 0)

    # ---------- build vertical segments delimited by wall columns ----------
    segments = []                     # list of (start, end) inclusive
    if not wall_cols:
        segments.append((0, w - 1))
    else:
        # segment left of first wall (excluding the wall itself)
        if wall_cols[0] > 0:
            segments.append((0, wall_cols[0] - 1))
        # middle segments: each starts at a wall column, ends before the next wall
        for i in range(len(wall_cols) - 1):
            l = wall_cols[i]
            r = wall_cols[i + 1] - 1
            if l <= r:
                segments.append((l, r))
        # last segment: starts at last wall column, goes to right edge
        if wall_cols[-1] < w:
            segments.append((wall_cols[-1], w - 1))

    # map each column to its segment index
    seg_of = [-1] * w
    for idx, (s, e) in enumerate(segments):
        for c in range(s, e + 1):
            seg_of[c] = idx

    # ---------- locate original 8 cells (seeds) ----------
    seeds = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not seeds:
        return out                     # nothing to do

    # ---------- decide horizontal direction ----------
    # direction: +1 = to the right, -1 = to the left
    if len(wall_cols) == 0:
        sign = 0
    elif len(wall_cols) == 1:
        wc = wall_cols[0]
        seg_idx = seg_of[seeds[0][1]]
        seg_start = segments[seg_idx][0]
        sign = 1 if wc <= seg_start else -1
    else:
        # several walls – they are all on one side of the seed segment
        seg_idx = seg_of[seeds[0][1]]
        seg_start = segments[seg_idx][0]
        seg_end = segments[seg_idx][1]
        if max(wall_cols) <= seg_start:          # walls on the left (or at boundary)
            sign = -1
        elif min(wall_cols) >= seg_end:          # walls on the right
            sign = 1
        else:
            # walls on both sides – default to right
            sign = 1

    # ---------- propagate each seed ----------
    for r0, c0 in seeds:
        seg_idx = seg_of[c0]
        for r in range(h):
            # number of active rows between r0 and r (exclusive of r0)
            if r == r0:
                shift = 0
            elif r > r0:
                shift = pref[r + 1] - pref[r0 + 1]
            else:  # r < r0
                shift = pref[r0] - pref[r]

            cand_seg = seg_idx + sign * shift

            # case: move to a different segment
            if 0 <= cand_seg < len(segments):
                if cand_seg != seg_idx:
                    s, e = segments[cand_seg]
                    for c in range(s, e + 1):
                        if out[r][c] != 2:
                            out[r][c] = 8
                else:
                    # same segment – just shift the column
                    nc = c0 + sign * shift
                    if 0 <= nc < w and out[r][nc] != 2:
                        out[r][nc] = 8
            else:
                # no segment to jump to – stay in the original segment
                nc = c0 + sign * shift
                if 0 <= nc < w and out[r][nc] != 2:
                    out[r][nc] = 8

    return out

